<?php /* VIVA NOTE: Landlord announcements and mark-read forms. */ ?><div class="toolbar"><p>Important news and updates published by BoardNest administrators.</p></div><div class="notice-list">
<?php foreach($announcements as $a):?><article class="panel notice-item"><div class="panel-title"><div><span class="eyebrow"><?=e(pill($a['priority']))?> · <?=e(date_label($a['published_at']))?></span><h3><?=e($a['title'])?></h3></div><span class="status"><?= $a['read_at']?'Read':'New' ?></span></div><p><?=nl2br(e($a['message']))?></p><?php if(!$a['read_at']):?><form method="post" action="<?=e(url('/announcements/read'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($a['announcement_id'])?>"><button class="btn small secondary">Mark as read</button></form><?php endif;?></article><?php endforeach;?><?php if(!$announcements):?><div class="panel empty">There are no active announcements.</div><?php endif;?></div>
